CREATE TABLE procurement_suppliers(id TEXT PRIMARY KEY,plant_id TEXT NOT NULL REFERENCES plants(id),workspace TEXT NOT NULL CHECK(workspace IN('demo','plant')),content TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('draft','approved','suspended')),version INTEGER NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),reviewed_by TEXT REFERENCES users(id),created_at TEXT NOT NULL);
CREATE TABLE procurement_quotes(id TEXT PRIMARY KEY,plant_id TEXT NOT NULL,workspace TEXT NOT NULL,supplier_id TEXT NOT NULL REFERENCES procurement_suppliers(id),part_id TEXT NOT NULL,content TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('draft','verified','withdrawn')),version INTEGER NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),verified_by TEXT REFERENCES users(id),created_at TEXT NOT NULL,FOREIGN KEY(plant_id,workspace,part_id) REFERENCES inventory_parts(plant_id,workspace,part_id));
CREATE TABLE procurement_events(id TEXT PRIMARY KEY,plant_id TEXT NOT NULL,workspace TEXT NOT NULL,resource_id TEXT NOT NULL,action TEXT NOT NULL,actor_id TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,reason TEXT NOT NULL,snapshot TEXT NOT NULL);
CREATE TABLE procurement_commands(actor_id TEXT NOT NULL REFERENCES users(id),request_key TEXT NOT NULL,payload TEXT NOT NULL,response TEXT NOT NULL,PRIMARY KEY(actor_id,request_key));
CREATE INDEX procurement_supplier_scope ON procurement_suppliers(plant_id,workspace);
CREATE INDEX procurement_quote_scope ON procurement_quotes(plant_id,workspace,part_id);
